rl = [
 R('N1RLa', '主張理解（長文）', '<p>人工知能の発達によって、多くの仕事が機械に置き換えられると言われている。単純な作業だけでなく、文章の作成や画像の判断といった、これまで人間にしかできないと考えられていた領域にまで、その影響は及びつつある。</p><p>こうした変化に対して、不安を抱く人は少なくない。だが、歴史を振り返れば、新しい技術は常に古い仕事を奪う一方で、新しい仕事を生み出してきた。重要なのは、技術を恐れることではなく、技術にはできないことは何かを見極め、そこに人間の力を注ぐことである。</p><p>では、機械にできないこととは何か。私は、問いを立てる力だと考える。人工知能は、与えられた問いに対しては驚くほど的確な答えを返す。しかし、何を問うべきか、なぜそれを問うのかを決めるのは、依然として人間の役割である。教育においても、正解を早く出す訓練から、良い問いを立てる訓練へと重心を移すべき時期に来ているのではないだろうか。</p>', [
  M('筆者によると、新しい技術は歴史的にどのような役割を果たしてきたか。', ['古い仕事を奪う一方で新しい仕事を生み出してきた', '仕事をすべて奪ってきた', '仕事に影響を与えなかった', '人間の能力を低下させてきた'], None, E('古い仕事を奪う一方で、新しい仕事を生み出してきた.', 'Destroyed and created jobs.')),
  M('筆者が考える「機械にできないこと」とは何か。', ['問いを立てること', '文章を作成すること', '画像を判断すること', '正確な答えを返すこと'], None, E('問いを立てる力.', 'Asking questions.')),
  M('筆者が教育について主張していることは何か。', ['良い問いを立てる訓練に重心を移すべきだ', '正解を早く出す訓練を強化すべきだ', '人工知能を教育に使うべきではない', '教師を機械に置き換えるべきだ'], None, E('良い問いを立てる訓練へ.', 'Shift to training good questions.'))]),
 R('N1RLb', '主張理解（長文）', '<p>「自分らしく生きる」という言葉をよく耳にする。他人の期待に縛られず、自分の価値観に従って生きることは、確かに大切だ。しかし、この言葉が、他者との関わりを軽視する言い訳として使われることがあるとすれば、それは本来の意味から外れているように思う。</p><p>そもそも「自分」というものは、他者との関係の中で形づくられる。家族や友人、職場の仲間との対話を通じて、私たちは自分が何を大切にし、何に違和感を覚えるのかを知る。他者を排除したところに残るのは、確固とした自分ではなく、むしろ輪郭のはっきりしない自分ではないだろうか。</p><p>自分らしさとは、孤立の中で守るものではなく、他者との摩擦や共感を経て、少しずつ磨かれていくものだと私は考える。</p>', [
  M('筆者が懸念していることは何か。', ['「自分らしく」が他者を軽視する言い訳になること', '他人の期待に応えられないこと', '価値観が多様化すること', '対話の機会が増えること'], None, E('他者との関わりを軽視する言い訳.', 'Used as an excuse to ignore others.')),
  M('筆者によると、「自分」はどのように形づくられるか。', ['他者との関係の中で', '孤立することで', '他人の期待に従うことで', '生まれつき決まっている'], None, E('他者との関係の中で形づくられる.', 'Through relationships.')),
  M('筆者の考える「自分らしさ」として最も適切なものはどれか。', ['他者との摩擦や共感を通じて磨かれるもの', '孤立の中で守るもの', '他人に合わせること', '変わらないもの'], None, E('摩擦や共感を経て磨かれていく.', 'Refined through interaction.'))]),
]
ri2 = [
 R('N1RTa', '統合理解', '<p><b>A</b>　大学入試に面接を広く導入すべきだ。筆記試験だけでは、受験生の意欲や人柄、表現力を測ることはできない。大学で主体的に学べる人材を選ぶには、対話を通じた評価が欠かせない。</p><p><b>B</b>　面接の拡大には慎重であるべきだ。面接は評価者の主観に左右されやすく、公平性の確保が難しい。また、話すことが得意な受験生が有利になり、思考力の高い生徒が正当に評価されないおそれもある。</p>', [
  M('AとBの共通点は何か。', ['入試で何を評価すべきかを問題にしている', '面接の全面廃止を主張している', '筆記試験の廃止を主張している', '大学の数を減らすべきだと考えている'], None, E('Keduanya membahas cara menilai calon.', 'Both concern what admissions should measure.')),
  M('Bが面接の問題点として挙げていることは何か。', ['評価が主観に左右されやすいこと', '時間がかかりすぎること', '費用が高いこと', '受験生が少ないこと'], None, E('評価者の主観に左右されやすく.', 'Subjectivity.'))]),
 R('N1RTb', '統合理解', '<p><b>A</b>　都市部への一極集中を是正するため、企業の本社機能の地方移転を進めるべきだ。地方に雇用が生まれれば、若者の流出も抑えられ、地域経済が活性化する。</p><p><b>B</b>　本社の地方移転は理想的だが、現実には課題が多い。取引先との距離が遠くなれば業務の効率が落ちるし、社員の家族の生活基盤をどう支えるかという問題もある。移転よりも、地方での新しい産業の育成に力を入れるべきではないか。</p>', [
  M('AとBは本社の地方移転についてどのように考えているか。', ['Aは推進すべきだとし、Bは課題が多いとしている', 'AもBも反対している', 'AもBも賛成している', 'Aは反対し、Bは賛成している'], None, E('A mendukung; B melihat banyak kendala.', 'A supports; B sees obstacles.')),
  M('Bが提案していることは何か。', ['地方で新しい産業を育てること', '本社をすべて地方に移すこと', '都市部の企業を増やすこと', '社員の家族を都市に住まわせること'], None, E('地方での新しい産業の育成.', 'Develop new local industries.'))]),
]
